import{_ as r,a0 as a,w as s,s as m,I as o,x as e,a1 as p,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"在LVM中設置精簡資源調配卷（第四部分） | LCTT x X-CMD","titleTemplate":false,"description":"在LVM中設置精簡資源調配卷（第四部分） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在LVM中設置精簡資源調配卷（第四部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在LVM中設置精簡資源調配卷（第四部分） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140828 Setup Thin Provisioning Volumes in Logical Volume Management (LVM)--Part IV","title":"在LVM中設置精簡資源調配卷（第四部分）","tag":"201411","desc":""},"relativePath":"201411/20140828 Setup Thin Provisioning Volumes in Logical Volume Management (LVM)--Part IV.md","filePath":"[post].md"}'),d={name:"201411/20140828 Setup Thin Provisioning Volumes in Logical Volume Management (LVM)--Part IV.md"};function g(c,t,h,u,w,_){const n=a("Link");return s(),m("div",null,[t[19]||(t[19]=o("h1",{id:"在lvm中設置精簡資源調配卷-第四部分",tabindex:"-1"},[e("在LVM中設置精簡資源調配卷（第四部分） "),o("a",{class:"header-anchor",href:"#在lvm中設置精簡資源調配卷-第四部分","aria-label":"Permalink to “在LVM中設置精簡資源調配卷（第四部分）”"},"​")],-1)),o("p",null,[t[1]||(t[1]=e("邏輯卷管理有許多特性，比如像快照和精簡資源調配。在先前（",-1)),p(n,{href:"http://linux.cn/article-4145-1.html"},{default:i(()=>[...t[0]||(t[0]=[e("第三部分",-1)])]),_:1}),t[2]||(t[2]=e("中），我們已經介紹瞭如何為邏輯卷創建快照。在本文中，我們將瞭解如何在LVM中設置精簡資源調配。",-1))]),t[20]||(t[20]=l('<p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Setup-Thin-Provisioning-in-LVM.jpg" alt="Setup Thin Provisioning in LVM"></p><p><em>在LVM中設置精簡資源調配</em></p><h3 id="精簡資源調配是什麼" tabindex="-1">精簡資源調配是什麼？ <a class="header-anchor" href="#精簡資源調配是什麼" aria-label="Permalink to “精簡資源調配是什麼？”">​</a></h3><p>精簡資源調配用於LVM以在精簡池中創建虛擬磁盤。我們假定我服務器上有<strong>15GB</strong>的存儲容量，而我已經有2個客户各自佔去了5GB存儲空間。你是第三個客户，你也請求5GB的存儲空間。在以前，我們會提供整個5GB的空間（富卷）。然而，你可能只使用5GB中的2GB，其它3GB以後再去填滿它。</p><p>而在精簡資源調配中我們所做的是，在其中一個大卷組中定義一個精簡池，再在精簡池中定義一個精簡卷。這樣，不管你寫入什麼文件，它都會保存進去，而你的存儲空間看上去就是5GB。然而，這所有5GB空間不會全部鋪滿整個硬盤。對其它客户也進行同樣的操作，就像我説的，那兒已經有兩個客户，你是第三個客户。</p><p>那麼，讓我們想想，我到底為客户分配了總計多少GB的空間呢？所有15GB的空間已經全部分配完了，如果現在有某個人來問我是否能提供5GB空間，我還可以分配給他麼？答案是“可以”。在精簡資源調配中，我可以為第四位客户分配5GB空間，即使我已經把那15GB的空間分配完了。</p><p><strong>警告</strong>：從那15GB空間中，如果我們對資源調配超過15GB了，那就是過度資源調配了。</p><h3 id="它是怎麼工作的-我們又是怎樣為客户提供存儲空間的" tabindex="-1">它是怎麼工作的？我們又是怎樣為客户提供存儲空間的？ <a class="header-anchor" href="#它是怎麼工作的-我們又是怎樣為客户提供存儲空間的" aria-label="Permalink to “它是怎麼工作的？我們又是怎樣為客户提供存儲空間的？”">​</a></h3><p>我已經提供給你5GB空間，但是你可能只用了2GB，而其它3GB還空閒着。在富資源調配中，我們不能這麼做，因為它一開始就分配了整個空間。</p><p>在精簡資源調配中，如果我為你定義了5GB空間，它就不會在定義卷時就將整個磁盤空間全部分配，它會根據你的數據寫入而增長，希望你看懂了！跟你一樣，其它客户也不會使用全部卷，所以還是有機會為一個新客户分配5GB空間的，這稱之為過度資源調配。</p><p>但是，必須對各個卷的增長情況進行監控，否則結局會是個災難。在過度資源調配完成後，如果所有4個客户都儘量寫入數據到磁盤，你將碰到問題了。因為這個動作會填滿15GB的存儲空間，甚至溢出，從而導致這些卷下線。</p><h3 id="前置閲讀" tabindex="-1">前置閲讀 <a class="header-anchor" href="#前置閲讀" aria-label="Permalink to “前置閲讀”">​</a></h3>',12)),o("ul",null,[o("li",null,[p(n,{href:"http://linux.cn/article-3965-1.html"},{default:i(()=>[...t[3]||(t[3]=[e("在Linux中使用LVM構建靈活的磁盤存儲（第一部分）",-1)])]),_:1})]),o("li",null,[p(n,{href:"http://linux.cn/article-3974-1.html"},{default:i(()=>[...t[4]||(t[4]=[e("在Linux中擴展/縮減LVM（第二部分）",-1)])]),_:1})]),o("li",null,[p(n,{href:"http://linux.cn/article-4145-1.html"},{default:i(()=>[...t[5]||(t[5]=[e("在 LVM中 錄製邏輯卷快照並恢復（第三部分）",-1)])]),_:1})])]),t[21]||(t[21]=l(`<h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><pre><code>操作系統 — 安裝有LVM的CentOS 6.5
服務器IP — 192.168.0.200
</code></pre><h3 id="步驟1-設置精簡池和卷" tabindex="-1">步驟1： 設置精簡池和卷 <a class="header-anchor" href="#步驟1-設置精簡池和卷" aria-label="Permalink to “步驟1： 設置精簡池和卷”">​</a></h3><p>理論講太多了，讓我們還是來點實際的吧，我們一起來設置精簡池和精簡卷。首先，我們需要一個大尺寸的卷組。這裏，我創建了一個<strong>15GB</strong>的卷組用於演示。現在，用下面的命令來列出卷組。</p><pre><code># vgcreate -s 32M vg_thin /dev/sdb1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Listing-Volume-Group.jpg" alt="Listing Volume Group"></p><p><em>列出卷組</em></p><p>接下來，在創建精簡池和精簡卷之前，檢查邏輯卷有多少空間可用。</p><pre><code># vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/check-Logical-Volume.jpg" alt="Check Logical Volume"></p><p><em>檢查邏輯卷</em></p><p>我們可以在上面的lvs命令輸出中看到，只顯示了一些默認邏輯用於文件系統和交換分區。</p><h3 id="創建精簡池" tabindex="-1">創建精簡池 <a class="header-anchor" href="#創建精簡池" aria-label="Permalink to “創建精簡池”">​</a></h3><p>使用以下命令在卷組（vg_thin）中創建一個15GB的精簡池。</p><pre><code># lvcreate -L 15G --thinpool tp_tecmint_pool vg_thin
</code></pre><ul><li><strong>-L</strong> – 卷組大小</li><li><strong>–thinpool</strong> – 創建精簡池</li><li><strong>tp_tecmint_poolThin</strong> - 精簡池名稱</li><li><strong>vg_thin</strong> – 我們需要創建精簡池的卷組名稱</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-Thin-Pool.jpg" alt="Create Thin Pool"></p><p><em>創建精簡池</em></p><p>使用‘lvdisplay’命令來查看詳細信息。</p><pre><code># lvdisplay vg_thin/tp_tecmint_pool
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Logical-Volume-Information.jpg" alt="Logical Volume Information"></p><p><em>邏輯卷信息</em></p><p>這裏，我們還沒有在該精簡池中創建虛擬精簡卷。在圖片中，我們可以看到分配的精簡池數據為<strong>0.00%</strong>。</p><h3 id="創建精簡卷" tabindex="-1">創建精簡卷 <a class="header-anchor" href="#創建精簡卷" aria-label="Permalink to “創建精簡卷”">​</a></h3><p>現在，我們可以在帶有-V（Virtual）選項的‘lvcreate’命令的幫助下，在精簡池中定義精簡捲了。</p><pre><code># lvcreate -V 5G --thin -n thin_vol_client1 vg_thin/tp_tecmint_pool
</code></pre><p>我已經在我的<strong>vg_thin</strong>卷組中的<strong>tp_tecmint_pool</strong>內創建了一個精簡虛擬卷，取名為<strong>thin_vol_client1</strong>。現在，使用下面的命令來列出邏輯卷。</p><pre><code># lvs 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/List-Logical-Volumes.jpg" alt="List Logical Volumes"></p><p><em>列出邏輯卷</em></p><p>剛才，我們已經在上面創建了精簡卷，這就是為什麼沒有數據，顯示為<strong>0.00%M</strong>。</p><p>好吧，讓我為其它2個客户再創建2個精簡卷。這裏，你可以看到在精簡池（<strong>tp_tecmint_pool</strong>）下有3個精簡捲了。所以，從這一點上看，我們開始明白，我已經使用所有15GB的精簡池。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-Thin-Volumes.jpg" alt="Create Thin Volumes"></p><h3 id="創建文件系統" tabindex="-1">創建文件系統 <a class="header-anchor" href="#創建文件系統" aria-label="Permalink to “創建文件系統”">​</a></h3><p>現在，使用下面的命令為這3個精簡卷創建掛載點並掛載，然後拷貝一些文件進去。</p><pre><code># mkdir -p /mnt/client1 /mnt/client2 /mnt/client3
</code></pre><p>列出創建的目錄。</p><pre><code># ls -l /mnt/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Creating-Mount-Points.jpg" alt="Creating Mount Points"></p><p><em>創建掛載點</em></p><p>使用‘mkfs’命令為這些創建的精簡卷創建文件系統。</p><pre><code># mkfs.ext4 /dev/vg_thin/thin_vol_client1 &amp;&amp; mkfs.ext4 /dev/vg_thin/thin_vol_client2 &amp;&amp; mkfs.ext4 /dev/vg_thin/thin_vol_client3
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-File-System.jpg" alt="Create File System"></p><p><em>創建文件系統</em></p><p>使用‘mount’命令來掛載所有3個客户捲到創建的掛載點。</p><pre><code># mount /dev/vg_thin/thin_vol_client1 /mnt/client1/ &amp;&amp; mount /dev/vg_thin/thin_vol_client2 /mnt/client2/ &amp;&amp; mount /dev/vg_thin/thin_vol_client3 /mnt/client3/
</code></pre><p>使用‘df’命令來列出掛載點。</p><pre><code># df -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Print-Mount-Points.jpg" alt="Print Mount Points"></p><p><em>顯示掛載點</em></p><p>這裏，我們可以看到所有3個客户卷已經掛載了，而每個客户卷只使用了3%的數據空間。那麼，讓我們從桌面添加一些文件到這3個掛載點，以填充一些空間。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Add-Files-To-Volumes.jpg" alt="Add Files To Volumes"></p><p><em>添加文件到卷</em></p><p>現在列出掛載點，並查看每個精簡卷使用的空間，然後列出精簡池來查看池中已使用的大小。</p><pre><code># df -h
# lvdisplay vg_thin/tp_tecmint_pool
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Mount-Point-Size.jpg" alt="Check Mount Point Size"></p><p><em>檢查掛載點大小</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Thin-Pool-Size.jpg" alt="Check Thin Pool Size"></p><p><em>檢查精簡池大小</em></p><p>上面的命令顯示了3個掛載點及其使用大小百分比。</p><pre><code>13% of datas used out of 5GB for client1
29% of datas used out of 5GB for client2
49% of datas used out of 5GB for client3
</code></pre><p>在查看精簡池時，我們看到總共只有<strong>30%</strong>的數據被寫入，這是上面3個客户虛擬卷的總使用量。</p><h3 id="過度資源調配" tabindex="-1">過度資源調配 <a class="header-anchor" href="#過度資源調配" aria-label="Permalink to “過度資源調配”">​</a></h3><p>現在，<strong>第四個</strong>客户來申請5GB的存儲空間。我能給他嗎？因為我已經把15GB的池分配給了3個客户。能不能再給另外一個客户分配5GB的空間呢？可以，這完全可能。在我們使用<strong>過度資源調配</strong>時，就可以實現。過度資源調配可以給我們比我們所擁有的更大的空間。</p><p>讓我來為第四位客户創建5GB的空間，然後再驗證一下大小吧。</p><pre><code># lvcreate -V 5G --thin -n thin_vol_client4 vg_thin/tp_tecmint_pool
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-thin-Storage.jpg" alt="Create thin Storage"></p><p><em>創建精簡存儲</em></p><p>在精簡池中，我只有15GB大小的空間，但是我已經在精簡池中創建了4個卷，其總量達到了20GB。如果4個客户都開始寫入數據到他們的卷，並將空間填滿，到那時我們將面對嚴峻的形勢。如果不填滿空間，那不會有問題。</p><p>現在，我已經創建在<strong>thin_vol_client4</strong>中創建了文件系統，然後掛載到了<strong>/mnt/client4</strong>下，並且拷貝了一些文件到裏頭。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Thing-Storage.jpg" alt="Verify Thin Storage"></p><p><em>驗證精簡存儲</em></p><p>我們可以在上面的圖片中看到，新創建的client 4總計使用空間達到了<strong>89.34%</strong>，而精簡池的已用空間達到了<strong>59.19</strong>。如果所有這些用户不再過度對卷寫入，那麼它就不會溢出，下線。要避免溢出的話，我們需要擴展精簡池大小。</p><p><strong>重要</strong>：精簡池只是一個邏輯卷，因此，如果我們需要對其進行擴展，我們可以使用和擴展邏輯卷一樣的命令，但我們不能縮減精簡池大小。</p><pre><code># lvextend
</code></pre><p>這裏，我們可以看到怎樣來擴展邏輯精簡池（<strong>tp_tecmint_pool</strong>）。</p><pre><code># lvextend -L +15G /dev/vg_thin/tp_tecmint_pool
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Extend-Thin-Storage.jpg" alt="Extend Thin Storage"></p><p><em>擴展精簡存儲</em></p><p>接下來，列出精簡池大小。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Thin-Storage.jpg" alt="Verify Thin Storage"></p><p><em>驗證精簡存儲</em></p><p>前面，我們的<strong>tp_tecmint_pool</strong>大小為15GB，而在對第四個精簡捲進行過度資源配置後達到了20GB。現在，它擴展到了30GB，所以我們的過度資源配置又迴歸常態，而精簡卷也不會溢出下線了。通過這種方式，我們可以添加更多的精簡捲到精簡池中。</p><p>在本文中，我們已經瞭解了怎樣來使用一個大尺寸的卷組創建一個精簡池，以及怎樣通過過度資源配置在精簡池中創建精簡卷和擴着精簡池。在下一篇文章中，我們將介紹怎樣來移除邏輯卷。</p><hr>`,87)),o("p",null,[t[7]||(t[7]=e("via: ",-1)),p(n,{href:"http://www.tecmint.com/setup-thin-provisioning-volumes-in-lvm/"},{default:i(()=>[...t[6]||(t[6]=[e("http://www.tecmint.com/setup-thin-provisioning-volumes-in-lvm/",-1)])]),_:1})]),o("p",null,[t[11]||(t[11]=e("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/babinlonston/"},{default:i(()=>[...t[8]||(t[8]=[e("Babin Lonston",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),p(n,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[9]||(t[9]=[e("GOLinux",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const L=r(d,[["render",g]]);export{V as __pageData,L as default};
